class Solution{public void setZeroes(int[][]m){int R=m.length,C=m[0].length;boolean r0=false,c0=false;for(int j=0;j<C;j++)r0|=m[0][j]==0;for(int i=0;i<R;i++)c0|=m[i][0]==0;for(int i=1;i<R;i++)for(int j=1;j<C;j++)if(m[i][j]==0)m[i][0]=m[0][j]=0;for(int i=1;i<R;i++)for(int j=1;j<C;j++)if(m[i][0]==0||m[0][j]==0)m[i][j]=0;if(r0)java.util.Arrays.fill(m[0],0);if(c0)for(int[]r:m)r[0]=0;}}
